public class MainActivityV4 extends Activity {
  private final int maroon=0xff700831,cream=0xfffcf8f0,gold=0xffcd932e,ink=0xff2d2226,muted=0xff75676b,border=0xffeddcbe,selected=0xfff7edf1;
  private FrameLayout root,drawer;private LinearLayout shell;private View scrim;private TextView title,sync;private WebView main,pre;private WebEngine web;private LaunchFlow launch;private boolean drawerOpen=false;private final List<LinearLayout> bottom=new ArrayList<>();
  private final String[][] primary={{"Home","/","nav_home"},{"Contests","/contests","nav_contests"},{"Events","/events","nav_events"},{"Businesses","/businesses","nav_businesses"},{"Account","/account","nav_account"}};
  private final String[][] menu={{"Home","Latest community highlights","/","nav_home"},{"Contests","Join and track devotional competitions","/contests","nav_contests"},{"Events","Celebrations and publishing services","/events","nav_events"},{"Businesses","Trusted community directory","/businesses","nav_businesses"},{"Winners","Selected participants and opportunities","/winners","nav_winners"},{"Journal","Devotional articles and stories","/blog","nav_journal"},{"Daily Quotes","A daily moment of remembrance","/blog/category/daily-quotes","nav_quotes"},{"Public Videos","Watch community videos","/videos","nav_videos"},{"Support","Help with submissions and account","/support","nav_support"},{"My Account","Profile, submissions and updates","/account","nav_account"}};
  private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private GradientDrawable round(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}private GradientDrawable outline(int c,int s,int r){GradientDrawable d=round(c,r);d.setStroke(dp(1),s);return d;}private int icon(String n){return getResources().getIdentifier(n,"drawable",getPackageName());}
  @Override public void onCreate(Bundle b){super.onCreate(b);SharedPreferences prefs=getSharedPreferences("sgn_app",MODE_PRIVATE);getWindow().setStatusBarColor(cream);getWindow().setNavigationBarColor(Color.WHITE);if(Build.VERSION.SDK_INT>=23)getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(false);build();web=new WebEngine(this,main,pre,sync,prefs);launch=new LaunchFlow(this,root,prefs);if(Build.VERSION.SDK_INT>=30)root.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets x=i.getInsets(WindowInsets.Type.systemBars());shell.setPadding(0,x.top,0,x.bottom);drawer.setPadding(0,x.top,0,x.bottom);return WindowInsets.CONSUMED;});String p="/";if(getIntent()!=null&&getIntent().getData()!=null){Uri u=getIntent().getData();p=u.getPath()==null?"/":u.getPath();if(u.getQuery()!=null)p+="?"+u.getQuery();}open(p);launch.show();web.startPreload();}
  private View menuButton(){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setGravity(Gravity.CENTER);b.setPadding(dp(12),dp(13),dp(12),dp(13));b.setBackground(outline(Color.WHITE,border,18));for(int i=0;i<3;i++){View l=new View(this);l.setBackgroundColor(i==1?gold:maroon);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(i==1?30:25),dp(3));if(i>0)p.topMargin=dp(5);b.addView(l,p);}return b;}
  private LinearLayout bottomItem(String[] x){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setGravity(Gravity.CENTER);b.setPadding(dp(3),dp(4),dp(3),dp(3));ImageView i=new ImageView(this);i.setImageResource(icon(x[2]));i.setScaleType(ImageView.ScaleType.CENTER_INSIDE);b.addView(i,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView t=new TextView(this);t.setText(x[0]);t.setTextColor(ink);t.setTextSize(10.5f);t.setGravity(Gravity.CENTER);b.addView(t,new LinearLayout.LayoutParams(-1,dp(20)));b.setOnClickListener(v->open(x[1]));bottom.add(b);return b;}
  private LinearLayout menuRow(String[] x){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(dp(8),dp(6),dp(8),dp(6));r.setBackground(round(Color.TRANSPARENT,20));ImageView i=new ImageView(this);i.setImageResource(icon(x[3]));i.setScaleType(ImageView.ScaleType.CENTER_INSIDE);r.addView(i,new LinearLayout.LayoutParams(dp(62),dp(62)));LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(10),0,0,0);TextView h=new TextView(this);h.setText(x[0]);h.setTextColor(ink);h.setTextSize(17);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);TextView s=new TextView(this);s.setText(x[1]);s.setTextColor(muted);s.setTextSize(11.5f);c.addView(h);c.addView(s);r.addView(c,new LinearLayout.LayoutParams(0,-2,1));TextView a=new TextView(this);a.setText("›");a.setTextColor(gold);a.setTextSize(28);a.setGravity(Gravity.CENTER);r.addView(a,new LinearLayout.LayoutParams(dp(30),dp(54)));r.setOnClickListener(v->{closeDrawer();open(x[2]);});return r;}
  private void build(){root=new FrameLayout(this);shell=new LinearLayout(this);shell.setOrientation(LinearLayout.VERTICAL);shell.setBackgroundColor(Color.WHITE);FrameLayout bar=new FrameLayout(this);bar.setBackgroundColor(cream);bar.setPadding(dp(14),dp(5),dp(14),dp(5));bar.setElevation(dp(2));View mb=menuButton();bar.addView(mb,new FrameLayout.LayoutParams(dp(58),dp(58),Gravity.START|Gravity.CENTER_VERTICAL));mb.setOnClickListener(v->openDrawer());title=new TextView(this);title.setTextColor(maroon);title.setTextSize(18);title.setTypeface(Typeface.SERIF,Typeface.BOLD);title.setGravity(Gravity.CENTER);bar.addView(title,new FrameLayout.LayoutParams(-2,dp(58),Gravity.CENTER));ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.sgn_mark);logo.setScaleType(ImageView.ScaleType.CENTER_INSIDE);bar.addView(logo,new FrameLayout.LayoutParams(dp(60),dp(60),Gravity.END|Gravity.CENTER_VERTICAL));shell.addView(bar,new LinearLayout.LayoutParams(-1,dp(72)));FrameLayout content=new FrameLayout(this);main=new WebView(this);content.addView(main,new FrameLayout.LayoutParams(-1,-1));shell.addView(content,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);nav.setPadding(dp(5),dp(3),dp(5),dp(3));nav.setBackgroundColor(Color.WHITE);nav.setElevation(dp(14));for(String[] x:primary){LinearLayout it=bottomItem(x);nav.addView(it,new LinearLayout.LayoutParams(0,dp(78),1));}shell.addView(nav,new LinearLayout.LayoutParams(-1,dp(84)));root.addView(shell,new FrameLayout.LayoutParams(-1,-1));scrim=new View(this);scrim.setBackgroundColor(0x77000000);scrim.setVisibility(View.GONE);scrim.setOnClickListener(v->closeDrawer());root.addView(scrim,new FrameLayout.LayoutParams(-1,-1));drawer=new FrameLayout(this);drawer.setBackgroundColor(cream);drawer.setElevation(dp(24));int w=Math.min(dp(360),(int)(getResources().getDisplayMetrics().widthPixels*.90));FrameLayout.LayoutParams dlp=new FrameLayout.LayoutParams(w,-1,Gravity.START);drawer.setLayoutParams(dlp);drawer.setTranslationX(-w);ScrollView sv=new ScrollView(this);sv.setFillViewport(true);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(16),dp(18),dp(16),dp(22));LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);ImageView big=new ImageView(this);big.setImageResource(R.drawable.sgn_mark);big.setScaleType(ImageView.ScaleType.CENTER_INSIDE);head.addView(big,new LinearLayout.LayoutParams(dp(90),dp(90)));LinearLayout hc=new LinearLayout(this);hc.setOrientation(LinearLayout.VERTICAL);hc.setPadding(dp(12),0,0,0);TextView h=new TextView(this);h.setText("Explore");h.setTextColor(maroon);h.setTextSize(24);h.setTypeface(Typeface.SERIF,Typeface.BOLD);TextView sub=new TextView(this);sub.setText("Spirituality • Creativity • Community");sub.setTextColor(muted);sub.setTextSize(11.5f);hc.addView(h);hc.addView(sub);head.addView(hc);list.addView(head,new LinearLayout.LayoutParams(-1,dp(104)));TextView sec=new TextView(this);sec.setText("MAIN SECTIONS");sec.setTextColor(muted);sec.setTextSize(11);sec.setTypeface(Typeface.DEFAULT,Typeface.BOLD);sec.setPadding(dp(8),dp(8),dp(8),dp(6));list.addView(sec);for(String[] x:menu)list.addView(menuRow(x),new LinearLayout.LayoutParams(-1,dp(78)));sync=new TextView(this);sync.setTextColor(muted);sync.setTextSize(11);sync.setGravity(Gravity.CENTER);sync.setPadding(dp(8),dp(16),dp(8),dp(14));list.addView(sync);sv.addView(list);drawer.addView(sv,new FrameLayout.LayoutParams(-1,-1));root.addView(drawer);pre=new WebView(this);pre.setAlpha(.01f);root.addView(pre,new FrameLayout.LayoutParams(dp(1),dp(1),Gravity.BOTTOM|Gravity.END));setContentView(root);}
  private String label(String p){if(p.startsWith("/contests"))return"Contests";if(p.startsWith("/events"))return"Events";if(p.startsWith("/businesses"))return"Businesses";if(p.startsWith("/winners"))return"Winners";if(p.startsWith("/blog/category/daily-quotes"))return"Daily Quotes";if(p.startsWith("/blog"))return"Journal";if(p.startsWith("/videos"))return"Videos";if(p.startsWith("/support"))return"Support";if(p.startsWith("/account"))return"Account";return"Home";}
  private void open(String p){if(p==null||p.isEmpty())p="/";title.setText(label(p));for(int i=0;i<bottom.size();i++){LinearLayout b=bottom.get(i);String t=primary[i][1];boolean active=t.equals("/")?p.equals("/"):p.startsWith(t);b.setBackground(round(active?selected:Color.TRANSPARENT,22));TextView l=(TextView)b.getChildAt(1);l.setTextColor(active?maroon:ink);l.setTypeface(Typeface.DEFAULT,active?Typeface.BOLD:Typeface.NORMAL);}web.load(p);}
  private void openDrawer(){if(drawerOpen)return;drawerOpen=true;scrim.setVisibility(View.VISIBLE);drawer.animate().translationX(0).setDuration(190).start();}private void closeDrawer(){if(!drawerOpen)return;drawerOpen=false;drawer.animate().translationX(-drawer.getWidth()).setDuration(190).withEndAction(()->scrim.setVisibility(View.GONE)).start();}
  @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);web.activityResult(r,c,d);}@Override public void onBackPressed(){if(launch!=null&&launch.visible()){launch.dismiss();return;}if(drawerOpen){closeDrawer();return;}if(web.canBack())web.back();else super.onBackPressed();}
}
